import { MenuAction, MenuView } from '@react-native-menu/menu'
import { ListFilter } from 'lucide-react-native'
import { NumberBadge } from '@/components'
import { defineStyles } from '@/utils/defineStyles'
import { SEARCH_BAR_HEIGHT } from '@/constants'
import { colors, useTheme } from '@/theme'
import { FilterConfig, FilterState } from '@/utils/createFilterStore'
import { LiquidGlassView } from '../LiquidGlassView'

type PressEvent = { nativeEvent: { event?: string; id?: string } }

type FilterButtonProps<T extends string = string> = {
	filterConfigs: FilterConfig<T>[]
	filterStore: FilterState<T>
}

export function FilterButton<T extends string = string>({
	filterConfigs,
	filterStore
}: FilterButtonProps<T>) {
	const { theme } = useTheme()
	const { hasFilter, toggleFilter, filtersCount } = filterStore

	const actions: MenuAction[] = filterConfigs.map((config) => ({
		id: config.id,
		title: config.title,
		state: hasFilter(config.id) ? 'on' : 'off'
	}))

	const handlePressAction = ({ nativeEvent }: PressEvent) => {
		const id = nativeEvent.event || nativeEvent.id
		const validFilter = filterConfigs.find((config) => config.id === id)
		if (validFilter) {
			toggleFilter(validFilter.id)
		}
	}

	return (
		<MenuView actions={actions} onPressAction={handlePressAction}>
			<LiquidGlassView
				isInteractive
				glassEffectStyle="regular"
				style={styles.filterButtonGlass}
				accessibilityRole="button"
				accessibilityLabel="Filter"
			>
				<ListFilter size={24} color={colors[theme].gray[900]} />
				<NumberBadge value={filtersCount} offset={-2} />
			</LiquidGlassView>
		</MenuView>
	)
}

const styles = defineStyles({
	filterButtonGlass: {
		width: SEARCH_BAR_HEIGHT,
		height: SEARCH_BAR_HEIGHT,
		borderRadius: 28,
		justifyContent: 'center',
		alignItems: 'center'
	}
})
